"""Step 5 on Kaggle: where the second GPU stops paying, 2x Tesla T4 over PCIe.

Single-file build. A Kaggle kernel is one process with no `torchrun`, so this
writes the three study scripts to disk unchanged and spawns the ranks itself,
setting the same environment variables torchrun would. Keeping the scripts
byte-identical to the repo versions means the Kaggle run and a local torchrun
run execute the same code.

Turing (sm_75) has no bf16. Every mixed-precision path here is fp16.

Generated from github lgoyal6 ddp-crossover; edit the sources, not this file.
"""
import os
import runpy
import sys

import torch
import torch.multiprocessing as mp

SOURCES = {
 "01_nccl_bench.py": "\"\"\"Step 5.1 -- raw NCCL collective bandwidth on 2x T4 over PCIe.\n\nThis is the roofline the training study needs: every gradient synchronization in\nDDP is an all-reduce, so the crossover where a second GPU stops paying is set by\nthis curve and by how much of a step is spent on it.\n\nTwo collectives, swept from a few KB to a few hundred MB:\n\n  * **all-reduce**, which is what DDP gradient sync uses.\n  * **all-gather**, which is what FSDP additionally needs for parameters, and is\n    the reason FSDP should be *worse* than DDP at small scale.\n\nBus bandwidth is reported alongside raw size/time, using NCCL's own convention:\nfor ring all-reduce each rank sends and receives 2*(N-1)/N of the buffer, so\nbus_bw = algbw * 2*(N-1)/N. Quoting algorithm bandwidth instead would flatter\nall-reduce by ~2x against all-gather and make the comparison meaningless.\n\nTuring (sm_75) has **no bf16**. Everything here is fp16 or fp32.\n\"\"\"\nfrom __future__ import annotations\n\nimport argparse\nimport json\nimport os\n\nimport torch\nimport torch.distributed as dist\n\n\ndef bench(fn, warmup=5, iters=20):\n    for _ in range(warmup):\n        fn()\n    torch.cuda.synchronize()\n    dist.barrier()\n    start, end = (torch.cuda.Event(enable_timing=True),\n                  torch.cuda.Event(enable_timing=True))\n    start.record()\n    for _ in range(iters):\n        fn()\n    end.record()\n    end.synchronize()\n    return start.elapsed_time(end) / 1e3 / iters\n\n\ndef main():\n    ap = argparse.ArgumentParser()\n    ap.add_argument(\"--dtype\", default=\"fp16\", choices=[\"fp16\", \"fp32\"])\n    ap.add_argument(\"--out\", default=\"results/nccl.json\")\n    a = ap.parse_args()\n\n    dist.init_process_group(\"nccl\")\n    rank = dist.get_rank()\n    world = dist.get_world_size()\n    torch.cuda.set_device(rank)\n    dt = torch.float16 if a.dtype == \"fp16\" else torch.float32\n    esize = 2 if dt == torch.float16 else 4\n\n    if rank == 0:\n        print(f\"world={world} dtype={a.dtype} \"\n              f\"device={torch.cuda.get_device_name(rank)} \"\n              f\"cap={torch.cuda.get_device_capability(rank)}\")\n        print(f\"\\n{'bytes':>12}{'MiB':>9}{'allreduce ms':>14}{'algbw GB/s':>12}\"\n              f\"{'busbw GB/s':>12}{'allgather ms':>14}{'ag busbw':>10}\")\n\n    sizes = [2**i for i in range(12, 29)]      # 4 KiB .. 256 MiB\n    rows = []\n    for nbytes in sizes:\n        n = nbytes // esize\n        try:\n            x = torch.ones(n, dtype=dt, device=rank)\n            g = torch.empty(n * world, dtype=dt, device=rank)\n        except torch.cuda.OutOfMemoryError:\n            break\n        iters = 20 if nbytes <= 2**24 else 5\n        t_ar = bench(lambda: dist.all_reduce(x), iters=iters)\n        t_ag = bench(lambda: dist.all_gather_into_tensor(g, x), iters=iters)\n\n        # NCCL convention. Ring all-reduce moves 2*(N-1)/N of the buffer per\n        # rank; all-gather moves (N-1)/N.\n        alg_ar = nbytes / t_ar / 1e9\n        bus_ar = alg_ar * 2 * (world - 1) / world\n        bus_ag = (nbytes / t_ag / 1e9) * (world - 1) / world\n        rows.append({\"bytes\": nbytes, \"allreduce_s\": t_ar,\n                     \"allreduce_algbw_gbs\": alg_ar,\n                     \"allreduce_busbw_gbs\": bus_ar,\n                     \"allgather_s\": t_ag, \"allgather_busbw_gbs\": bus_ag})\n        if rank == 0:\n            print(f\"{nbytes:>12}{nbytes/2**20:>9.2f}{t_ar*1e3:>14.3f}\"\n                  f\"{alg_ar:>12.2f}{bus_ar:>12.2f}{t_ag*1e3:>14.3f}\"\n                  f\"{bus_ag:>10.2f}\")\n        del x, g\n        torch.cuda.empty_cache()\n\n    if rank == 0:\n        peak = max(r[\"allreduce_busbw_gbs\"] for r in rows)\n        small = rows[0]\n        print(f\"\\npeak all-reduce bus bandwidth: {peak:.2f} GB/s\")\n        print(f\"small-message latency floor ({small['bytes']} B): \"\n              f\"{small['allreduce_s']*1e6:.1f} us\")\n        half = peak / 2\n        cross = next((r[\"bytes\"] for r in rows\n                      if r[\"allreduce_busbw_gbs\"] >= half), None)\n        print(f\"reaches half of peak at {cross} bytes \"\n              f\"({cross/2**20:.2f} MiB)\" if cross else \"\")\n        os.makedirs(os.path.dirname(a.out), exist_ok=True)\n        with open(a.out, \"w\") as f:\n            json.dump({\"world\": world, \"dtype\": a.dtype,\n                       \"device\": torch.cuda.get_device_name(0),\n                       \"peak_allreduce_busbw_gbs\": peak, \"rows\": rows}, f,\n                      indent=2)\n        print(f\"wrote {a.out}\")\n    dist.destroy_process_group()\n\n\nif __name__ == \"__main__\":\n    main()\n",
 "02_ddp_sweep.py": "\"\"\"Step 5.2/5.3/5.4 -- where does the second GPU stop paying, and what moves it.\n\nTrains the same model 1-GPU and 2-GPU DDP across a parameter-count sweep and\nfinds the size below which 2-GPU throughput falls *below* 1-GPU. The small\nhardware is the point: 2x T4 over PCIe with no NVLink is the regime where\ninterconnect cost is visible, and the finding is about the interconnect.\n\nAll-reduce fraction of step time is instrumented directly rather than inferred,\nby timing the backward pass with and without gradient synchronization\n(`model.no_sync()` suppresses the all-reduce while doing identical compute), so\nthe difference is the synchronization cost and nothing else.\n\nMitigations swept, each of which moves the crossover for a different reason:\n\n  * `bucket_cap_mb` -- how much gradient is coalesced per all-reduce. Small\n    buckets mean more, smaller collectives, and the NCCL curve from\n    01_nccl_bench.py shows small messages are latency-bound.\n  * gradient accumulation -- syncs once per K micro-batches instead of every\n    one, which divides communication by K and is the bluntest fix available.\n  * fp16 gradient compression via a DDP comm hook -- halves the bytes on the\n    wire. **fp16, not bf16**: T4 is Turing (sm_75) and has no bf16 support at\n    all, so a bf16 hook would either fail or silently emulate.\n  * FSDP vs DDP at the same size -- FSDP adds an all-gather of parameters on top\n    of the gradient reduce-scatter, so at small scale it should be *worse*, and\n    that is the counterintuitive part worth measuring rather than asserting.\n\nThroughput is samples/second across both ranks, so a perfectly scaling 2-GPU run\nis 2.0x and anything below 1.0x means the second GPU is actively harmful.\n\"\"\"\nfrom __future__ import annotations\n\nimport argparse\nimport contextlib\nimport json\nimport os\nimport time\n\nimport torch\nimport torch.distributed as dist\nimport torch.nn as nn\nfrom torch.nn.parallel import DistributedDataParallel as DDP\n\n\nclass MLP(nn.Module):\n    \"\"\"Plain stack of square linears, so parameter count is a clean dial.\n\n    Deliberately not a transformer: the question is how communication volume\n    trades against compute, and an MLP lets parameter count be swept smoothly\n    without also changing attention cost, sequence length or memory layout.\n    \"\"\"\n\n    def __init__(self, width: int, depth: int, n_classes: int = 64):\n        super().__init__()\n        layers = []\n        for _ in range(depth):\n            layers += [nn.Linear(width, width), nn.ReLU()]\n        self.body = nn.Sequential(*layers)\n        self.head = nn.Linear(width, n_classes)\n\n    def forward(self, x):\n        return self.head(self.body(x))\n\n\ndef fp16_compress_hook(state, bucket):\n    \"\"\"Cast the bucket to fp16 for the wire, all-reduce, cast back.\n\n    torch ships `default_hooks.fp16_compress_hook`; this is written out so the\n    bytes-on-the-wire claim is visible rather than taken on trust.\n    \"\"\"\n    group = state if state is not None else dist.group.WORLD\n    world = dist.get_world_size(group)\n    buf = bucket.buffer().to(torch.float16).div_(world)\n    fut = dist.all_reduce(buf, group=group, async_op=True).get_future()\n\n    def decompress(f):\n        return f.value()[0].to(bucket.buffer().dtype)\n\n    return fut.then(decompress)\n\n\ndef build(width, depth, device):\n    torch.manual_seed(0)\n    return MLP(width, depth).to(device)\n\n\ndef n_params(m):\n    return sum(p.numel() for p in m.parameters())\n\n\ndef train_steps(model, opt, batch, width, device, steps, accum=1,\n                no_sync_probe=False):\n    \"\"\"Return (seconds per optimizer step, seconds of gradient sync per step).\n\n    `no_sync_probe` reruns the same work with DDP's all-reduce suppressed; the\n    difference isolates communication from compute.\n    \"\"\"\n    x = torch.randn(batch, width, device=device)\n    y = torch.randint(0, 64, (batch,), device=device)\n    lossf = nn.CrossEntropyLoss()\n\n    def one_step(sync=True):\n        opt.zero_grad(set_to_none=True)\n        for k in range(accum):\n            last = (k == accum - 1)\n            # DDP all-reduces on the last backward of an accumulation group.\n            # Suppress it for every earlier micro-batch, and for all of them\n            # when probing the no-communication baseline.\n            skip = isinstance(model, DDP) and (not last or not sync)\n            ctx = model.no_sync() if skip else contextlib.nullcontext()\n            with ctx:\n                lossf(model(x), y).backward()\n        opt.step()\n\n    for _ in range(5):\n        one_step()\n    torch.cuda.synchronize()\n    if dist.is_initialized():\n        dist.barrier()\n\n    t0 = time.perf_counter()\n    for _ in range(steps):\n        one_step(sync=True)\n    torch.cuda.synchronize()\n    t_sync = (time.perf_counter() - t0) / steps\n\n    t_nosync = t_sync\n    if no_sync_probe and isinstance(model, DDP):\n        torch.cuda.synchronize()\n        t0 = time.perf_counter()\n        for _ in range(steps):\n            one_step(sync=False)\n        torch.cuda.synchronize()\n        t_nosync = (time.perf_counter() - t0) / steps\n    return t_sync, max(0.0, t_sync - t_nosync)\n\n\ndef main():\n    ap = argparse.ArgumentParser()\n    ap.add_argument(\"--widths\", type=int, nargs=\"*\",\n                    default=[256, 512, 1024, 2048, 4096, 8192])\n    ap.add_argument(\"--depth\", type=int, default=8)\n    ap.add_argument(\"--batch\", type=int, default=256)\n    ap.add_argument(\"--steps\", type=int, default=30)\n    ap.add_argument(\"--bucket-mbs\", type=int, nargs=\"*\", default=[25])\n    ap.add_argument(\"--accums\", type=int, nargs=\"*\", default=[1])\n    ap.add_argument(\"--fp16-hook\", action=\"store_true\")\n    ap.add_argument(\"--fsdp\", action=\"store_true\")\n    ap.add_argument(\"--tag\", default=\"ddp\")\n    ap.add_argument(\"--out\", default=\"results/ddp_sweep.json\")\n    a = ap.parse_args()\n\n    ddp = \"RANK\" in os.environ\n    if ddp:\n        dist.init_process_group(\"nccl\")\n        rank, world = dist.get_rank(), dist.get_world_size()\n        torch.cuda.set_device(rank)\n        device = torch.device(\"cuda\", rank)\n    else:\n        rank, world, device = 0, 1, torch.device(\"cuda\", 0)\n\n    if rank == 0:\n        print(f\"{a.tag}: world={world} depth={a.depth} batch={a.batch} \"\n              f\"device={torch.cuda.get_device_name(0)} \"\n              f\"cap={torch.cuda.get_device_capability(0)}\")\n        hdr = (f\"\\n{'width':>7}{'params_M':>10}{'grad_MiB':>10}{'bucket':>8}\"\n               f\"{'accum':>7}{'s/step':>10}{'samples/s':>12}{'comm_ms':>10}\"\n               f\"{'comm%':>8}\")\n        print(hdr)\n\n    rows = []\n    for width in a.widths:\n        for bucket in a.bucket_mbs:\n            for accum in a.accums:\n                model = build(width, a.depth, device)\n                p = n_params(model)\n                if ddp:\n                    if a.fsdp:\n                        from torch.distributed.fsdp import FullyShardedDataParallel as FSDP\n                        model = FSDP(model, device_id=rank)\n                    else:\n                        model = DDP(model, device_ids=[rank],\n                                    bucket_cap_mb=bucket)\n                        if a.fp16_hook:\n                            model.register_comm_hook(None, fp16_compress_hook)\n                opt = torch.optim.SGD(model.parameters(), lr=0.01)\n                t, comm = train_steps(model, opt, a.batch, width, device,\n                                      a.steps, accum=accum,\n                                      no_sync_probe=ddp and not a.fsdp)\n                # samples/s counts every rank's batch and every accumulation\n                # micro-batch, so 1-GPU and 2-GPU numbers are comparable.\n                sps = a.batch * accum * world / t\n                rows.append({\n                    \"tag\": a.tag, \"world\": world, \"width\": width,\n                    \"params\": p, \"grad_mib\": p * 4 / 2**20,\n                    \"bucket_mb\": bucket, \"accum\": accum,\n                    \"fp16_hook\": a.fp16_hook, \"fsdp\": a.fsdp,\n                    \"s_per_step\": t, \"samples_per_s\": sps,\n                    \"comm_s\": comm, \"comm_frac\": comm / t if t else 0.0,\n                })\n                if rank == 0:\n                    print(f\"{width:>7}{p/1e6:>10.2f}{p*4/2**20:>10.1f}\"\n                          f\"{bucket:>8}{accum:>7}{t*1e3:>10.2f}{sps:>12.0f}\"\n                          f\"{comm*1e3:>10.2f}{100*comm/t:>7.1f}%\")\n                del model, opt\n                torch.cuda.empty_cache()\n\n    if rank == 0:\n        os.makedirs(os.path.dirname(a.out), exist_ok=True)\n        prev = []\n        if os.path.exists(a.out):\n            with open(a.out) as f:\n                prev = json.load(f).get(\"rows\", [])\n        with open(a.out, \"w\") as f:\n            json.dump({\"rows\": prev + rows}, f, indent=2)\n        print(f\"\\nwrote {a.out} ({len(prev)+len(rows)} rows total)\")\n    if ddp:\n        dist.destroy_process_group()\n\n\nif __name__ == \"__main__\":\n    main()\n",
 "03_report.py": "\"\"\"Step 5 gate: the crossover, the all-reduce fraction curve, and what each\nmitigation recovers.\"\"\"\nfrom __future__ import annotations\n\nimport argparse\nimport json\nimport os\n\n\ndef load(path):\n    if not os.path.exists(path):\n        return []\n    with open(path) as f:\n        return json.load(f).get(\"rows\", [])\n\n\ndef main():\n    ap = argparse.ArgumentParser()\n    ap.add_argument(\"--sweep\", default=\"results/ddp_sweep.json\")\n    ap.add_argument(\"--nccl\", default=\"results/nccl_fp16.json\")\n    a = ap.parse_args()\n\n    rows = load(a.sweep)\n    if not rows:\n        print(f\"no rows in {a.sweep}; run run_all.sh first\")\n        return\n\n    def pick(tag, **kw):\n        out = [r for r in rows if r[\"tag\"] == tag\n               and all(r.get(k) == v for k, v in kw.items())]\n        return {r[\"width\"]: r for r in out}\n\n    one = pick(\"1gpu\")\n    two = pick(\"2gpu_ddp\", bucket_mb=25, accum=1)\n\n    print(\"=== crossover: does the second GPU pay? ===\")\n    print(f\"{'width':>7}{'params_M':>10}{'grad_MiB':>10}{'1gpu sps':>11}\"\n          f\"{'2gpu sps':>11}{'scaling':>9}{'comm%':>8}  verdict\")\n    crossover = None\n    for w in sorted(set(one) & set(two)):\n        o, t = one[w], two[w]\n        sc = t[\"samples_per_s\"] / o[\"samples_per_s\"]\n        v = (\"2 GPUs SLOWER\" if sc < 1.0\n             else \"sublinear\" if sc < 1.6 else \"scales\")\n        if sc < 1.0:\n            crossover = w\n        print(f\"{w:>7}{t['params']/1e6:>10.2f}{t['grad_mib']:>10.1f}\"\n              f\"{o['samples_per_s']:>11.0f}{t['samples_per_s']:>11.0f}\"\n              f\"{sc:>9.2f}{100*t['comm_frac']:>7.1f}%  {v}\")\n\n    if crossover:\n        bigger = [w for w in sorted(set(one) & set(two))\n                  if two[w][\"samples_per_s\"] / one[w][\"samples_per_s\"] >= 1.0]\n        nxt = min(bigger) if bigger else None\n        print(f\"\\nCROSSOVER: 2-GPU DDP is slower than 1 GPU at width <= \"\n              f\"{crossover} ({two[crossover]['params']/1e6:.2f}M params, \"\n              f\"{two[crossover]['grad_mib']:.1f} MiB of gradient)\"\n              + (f\"; it starts paying at width {nxt} \"\n                 f\"({two[nxt]['params']/1e6:.2f}M params)\" if nxt else \"\"))\n    else:\n        print(\"\\nNo crossover in this sweep: 2 GPUs were never slower. \"\n              \"Extend --widths downward.\")\n\n    nccl = load(a.nccl)\n    if nccl:\n        peak = max(r[\"allreduce_busbw_gbs\"] for r in nccl)\n        floor = nccl[0][\"allreduce_s\"] * 1e6\n        print(f\"\\nNCCL context: peak all-reduce bus bandwidth {peak:.2f} GB/s, \"\n              f\"small-message floor {floor:.1f} us\")\n        print(\"A gradient buffer that is small enough to sit on the latency \"\n              \"floor pays the same cost no matter how small it gets, which is \"\n              \"what makes the second GPU a net loss below the crossover.\")\n\n    print(\"\\n=== what each mitigation recovers ===\")\n    base = two\n    for tag, label, key in ((\"bucket\", \"bucket_cap_mb\", \"bucket_mb\"),\n                            (\"accum\", \"grad accumulation\", \"accum\"),\n                            (\"fp16hook\", \"fp16 grad compression\", None),\n                            (\"fsdp\", \"FSDP instead of DDP\", None)):\n        got = [r for r in rows if r[\"tag\"] == tag]\n        if not got:\n            continue\n        print(f\"\\n  {label}\")\n        vals = sorted({r[key] for r in got}) if key else [None]\n        print(f\"{'width':>9}\" + \"\".join(\n            f\"{(str(v) if v is not None else tag):>12}\" for v in vals)\n            + f\"{'baseline':>12}\")\n        for w in sorted({r[\"width\"] for r in got}):\n            line = f\"{w:>9}\"\n            for v in vals:\n                m = [r for r in got if r[\"width\"] == w\n                     and (key is None or r[key] == v)]\n                line += f\"{(m[0]['samples_per_s'] if m else float('nan')):>12.0f}\"\n            b = base.get(w)\n            line += f\"{(b['samples_per_s'] if b else float('nan')):>12.0f}\"\n            print(line)\n\n\nif __name__ == \"__main__\":\n    main()\n"
}


def materialize():
    for name, src in SOURCES.items():
        with open(name, "w") as f:
            f.write(src)
    print(f"wrote {len(SOURCES)} study scripts: {sorted(SOURCES)}")


def _worker(rank, world, script, argv, port):
    os.environ.update({
        "RANK": str(rank), "LOCAL_RANK": str(rank), "WORLD_SIZE": str(world),
        "MASTER_ADDR": "127.0.0.1", "MASTER_PORT": port,
    })
    sys.argv = [script] + argv
    runpy.run_path(script, run_name="__main__")


def launch(script, argv, world=2, port="29517"):
    print(f"\n$ [{world} ranks] {script} {' '.join(argv)}", flush=True)
    mp.spawn(_worker, args=(world, script, argv, port), nprocs=world, join=True)


def single(script, argv):
    print(f"\n$ [1 rank] {script} {' '.join(argv)}", flush=True)
    for k in ("RANK", "LOCAL_RANK", "WORLD_SIZE", "MASTER_ADDR", "MASTER_PORT"):
        os.environ.pop(k, None)
    sys.argv = [script] + argv
    runpy.run_path(script, run_name="__main__")


def diagnose():
    """Report what the container actually gave us before failing on it."""
    import subprocess
    print("=== container diagnostics ===")
    print("torch:", torch.__version__, "| torch.version.cuda:",
          torch.version.cuda, "| cuda available:", torch.cuda.is_available())
    print("CUDA_VISIBLE_DEVICES:", os.environ.get("CUDA_VISIBLE_DEVICES"))
    try:
        r = subprocess.run(["nvidia-smi", "--query-gpu=name,memory.total",
                            "--format=csv,noheader"],
                           capture_output=True, text=True, timeout=30)
        print("nvidia-smi rc:", r.returncode, "|", r.stdout.strip() or r.stderr.strip()[:200])
    except FileNotFoundError:
        print("nvidia-smi: not present (CPU-only image)")
    except Exception as e:
        print("nvidia-smi failed:", type(e).__name__, e)


def main():
    diagnose()
    n = torch.cuda.device_count()
    print(f"torch {torch.__version__} | visible GPUs: {n} -> "
          f"{[torch.cuda.get_device_name(i) for i in range(n)]} "
          f"{[torch.cuda.get_device_capability(i) for i in range(n)]}")
    if n < 2:
        raise SystemExit(
            f"This study needs 2 GPUs and sees {n}. Set Kaggle "
            "Settings > Accelerator > GPU T4 x2. A one-GPU run would emit a "
            "table of 1.00x scaling that looks like a finding. If torch reports "
            "a +cpu build above, the container had no CUDA at all, which means "
            "the accelerator was not attached rather than merely being single.")
    materialize()
    os.makedirs("results", exist_ok=True)

    launch("01_nccl_bench.py", ["--dtype", "fp16", "--out", "results/nccl_fp16.json"])
    launch("01_nccl_bench.py", ["--dtype", "fp32", "--out", "results/nccl_fp32.json"])
    single("02_ddp_sweep.py", ["--tag", "1gpu"])
    launch("02_ddp_sweep.py", ["--tag", "2gpu_ddp"])
    launch("02_ddp_sweep.py", ["--tag", "bucket", "--bucket-mbs", "1", "5", "25", "100"])
    launch("02_ddp_sweep.py", ["--tag", "accum", "--accums", "1", "2", "4", "8"])
    launch("02_ddp_sweep.py", ["--tag", "fp16hook", "--fp16-hook"])
    launch("02_ddp_sweep.py", ["--tag", "fsdp", "--fsdp"])
    single("03_report.py", [])

    print("\n=== raw JSON for retrieval ===")
    import json as _j
    for f in sorted(os.listdir("results")):
        print(f"\n----8<---- results/{f} ----8<----")
        print(_j.dumps(_j.load(open(f"results/{f}"))))


if __name__ == "__main__":
    mp.set_start_method("spawn", force=True)
    main()
